import{_ as t,o as i,c as s,ag as e}from"./chunks/framework.DoUXNnsN.js";const c=JSON.parse('{"title":"操作系统","description":"","frontmatter":{"title":"操作系统","aliases":["OS","Operating System","操作系统原理"],"tags":["计算机基础","操作系统"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Operating_system","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"10-计算机基础/操作系统/操作系统.md","filePath":"10-计算机基础/操作系统/操作系统.md"}'),l={name:"10-计算机基础/操作系统/操作系统.md"};function h(r,a,n,d,o,p){return i(),s("div",null,[...a[0]||(a[0]=[e(`<blockquote><p>本篇是&quot;操作系统&quot;小系列的总览页。读完你应该能：说出操作系统到底管哪几件事；知道后面五篇各讲什么，以及按什么顺序看。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>操作系统（Operating System，OS，如 Windows、Linux）是夹在硬件和应用程序之间的一层软件，负责把 CPU、内存、磁盘等资源公平、安全地分给各个程序用，并给程序提供统一的使用方式。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/10-计算机基础/计算机组成/计算机组成">计算机组成</a>：知道 CPU、内存、磁盘分别是什么。</li><li><a href="/Encyclopedia/10-计算机基础/计算机组成/CPU与指令执行">CPU与指令执行</a>：知道 CPU 一次只执行一条指令流。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>假设没有操作系统，你的程序要自己控制磁盘的每个扇区、自己和别的程序抢 CPU、自己防止写坏别人的内存。每写一个程序都要重写这些，而且一个程序出错整台电脑就崩了。操作系统把这些&quot;脏活&quot;集中处理，程序员只需要说&quot;打开一个文件&quot;&quot;开一个线程&quot;。</p><p>类比：操作系统像一栋写字楼的物业。公司（程序）不用自己接水电、管电梯、保安；物业统一分配，保证不同公司互不干扰，还给大家一个统一的前台（系统调用）。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="操作系统的五件事" tabindex="-1">操作系统的五件事 <a class="header-anchor" href="#操作系统的五件事" aria-label="Permalink to &quot;操作系统的五件事&quot;">​</a></h3><table tabindex="0"><thead><tr><th>管什么</th><th>对应的问题</th><th>本系列的篇目</th></tr></thead><tbody><tr><td>处理器</td><td>一个 CPU 怎么&quot;同时&quot;跑很多程序</td><td><a href="/Encyclopedia/10-计算机基础/操作系统/进程与线程">进程与线程</a></td></tr><tr><td>内存</td><td>每个程序以为自己独占一大片内存</td><td><a href="/Encyclopedia/10-计算机基础/操作系统/内存管理与虚拟内存">内存管理与虚拟内存</a></td></tr><tr><td>存储</td><td>磁盘上的字节怎么变成文件和目录</td><td><a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a></td></tr><tr><td>同步</td><td>多个程序/线程抢同一份数据怎么办</td><td><a href="/Encyclopedia/10-计算机基础/操作系统/并发与锁">并发与锁</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/死锁">死锁</a></td></tr><tr><td>设备</td><td>键盘、网卡、串口怎么统一访问</td><td>驱动程序（本系列略）</td></tr></tbody></table><h3 id="内核态与用户态" tabindex="-1">内核态与用户态 <a class="header-anchor" href="#内核态与用户态" aria-label="Permalink to &quot;内核态与用户态&quot;">​</a></h3><p>CPU 提供两种运行级别：<strong>内核态</strong>（可以做任何事，操作系统内核在这里运行）和<strong>用户态</strong>（受限，普通程序在这里）。程序要读文件、开网络连接，必须通过<strong>系统调用</strong>（system call）请求内核代劳。这样一个普通程序崩溃，不会把整个系统带崩。</p><h3 id="常见操作系统" tabindex="-1">常见操作系统 <a class="header-anchor" href="#常见操作系统" aria-label="Permalink to &quot;常见操作系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>常见场景</th></tr></thead><tbody><tr><td>Windows</td><td>办公电脑、工控机、MES 客户端；你的 C# + SQL Server 栈的主要运行环境</td></tr><tr><td>Linux</td><td>服务器、容器、嵌入式、大量工业网关</td></tr><tr><td>实时操作系统（RTOS）</td><td>PLC、运动控制：必须在规定的毫秒内响应</td></tr></tbody></table><h3 id="一个程序的-一生" tabindex="-1">一个程序的&quot;一生&quot; <a class="header-anchor" href="#一个程序的-一生" aria-label="Permalink to &quot;一个程序的&quot;一生&quot;&quot;">​</a></h3><p>在 Windows 上双击 <code>app.exe</code>：操作系统创建一个<strong>进程</strong>，把程序读进内存，给它分配一个虚拟地址空间，启动一个主<strong>线程</strong>，调度器决定它什么时候用 CPU；程序读写的文件由文件系统管理；多个线程访问共享数据，要靠锁。这一路几乎涵盖本系列所有内容。</p><h2 id="逐步例子-看一眼系统里正在发生什么" tabindex="-1">逐步例子：看一眼系统里正在发生什么 <a class="header-anchor" href="#逐步例子-看一眼系统里正在发生什么" aria-label="Permalink to &quot;逐步例子：看一眼系统里正在发生什么&quot;">​</a></h2><p>打开 PowerShell，查看占用内存最多的 3 个进程：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Sort-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WorkingSet64 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Descending </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ProcessName</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> @</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MB&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.WorkingSet64</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)}}</span></span></code></pre></div><p>你会看到 PID（进程编号）、名字、占用的物理内存 MB。每个进程都是操作系统管理的一个&quot;账户&quot;。具体数字因机器而异，这里不贴本机输出。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>在 Python 里让操作系统告诉你它的信息（<code>platform</code> 和 <code>os</code> 是标准库，实验在下面各篇会陆续深入）：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os, platform</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(platform.system(), platform.release(), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;逻辑处理器:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, os.cpu_count(), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的PID:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, os.getpid())</span></span></code></pre></div><p>本机实测输出（因机器而异）：<code>Windows 11 逻辑处理器: 16 我的PID: ...</code>（PID 每次运行不同）。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>提示</th></tr></thead><tbody><tr><td>程序&quot;没响应&quot;</td><td>主线程被卡住（死循环、在等锁、在等网络），见 <a href="/Encyclopedia/10-计算机基础/操作系统/死锁">死锁</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/进程与线程">进程与线程</a></td></tr><tr><td>内存占用高但机器不卡</td><td>操作系统会把空闲内存拿来做文件缓存，这是好事，见 <a href="/Encyclopedia/10-计算机基础/操作系统/内存管理与虚拟内存">内存管理与虚拟内存</a></td></tr><tr><td>同样的 Python 脚本在 Windows 和 Linux 表现不同</td><td>路径分隔符、文件系统大小写、多进程启动方式不同，见 <a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/进程与线程">进程与线程</a></td></tr></tbody></table><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：工厂的 MES 服务器多是 Windows Server，产线边缘设备常是 Linux 或 RTOS。系统的稳定性、补丁策略和权限管理，决定了系统能不能 7×24 小时运行。</li><li><strong>技术视角</strong>：C# 里的 <code>Thread</code>、<code>Task</code>、<code>lock</code>，都是对操作系统线程和同步原语的封装；理解 OS 层才知道它们的代价和边界。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>操作系统主要管理哪几类资源？ <strong>答</strong>：处理器、内存、存储（文件）、设备，并提供同步机制。</li><li>为什么普通程序读文件要通过系统调用？ <strong>答</strong>：只有内核态能直接操作硬件，系统调用让内核替程序安全地完成，也能防止程序互相干扰。</li><li>工控的 PLC 为什么常用实时操作系统？ <strong>答</strong>：要在严格的时间期限内响应，普通系统的调度无法保证。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>操作系统 = 资源管理者 + 统一接口提供者。</li><li>用户态程序通过系统调用请求内核服务。</li><li>后面五篇依次讲：进程线程、内存、文件、并发、死锁。</li></ul><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li><a href="/Encyclopedia/10-计算机基础/操作系统/进程与线程">进程与线程</a>：程序运行起来是什么样，CPU 怎么在程序之间切换。</li><li><a href="/Encyclopedia/10-计算机基础/操作系统/内存管理与虚拟内存">内存管理与虚拟内存</a>：每个程序为什么以为自己独占内存。</li><li><a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a>：磁盘上的字节怎么变成文件、目录和路径。</li><li><a href="/Encyclopedia/10-计算机基础/操作系统/并发与锁">并发与锁</a>：多个线程同时改同一数据会出什么错，怎么解决（并联系 MES 工单报工）。</li><li><a href="/Encyclopedia/10-计算机基础/操作系统/死锁">死锁</a>：加锁加出来的新问题，怎么检测、怎么避免。</li></ol><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/10-计算机基础/计算机基础">计算机基础</a>、<a href="/Encyclopedia/10-计算机基础/计算机组成/计算机组成">计算机组成</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/进程与线程">进程与线程</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/内存管理与虚拟内存">内存管理与虚拟内存</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/文件系统">文件系统</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/并发与锁">并发与锁</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/死锁">死锁</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Wikipedia: Operating system（<a href="https://en.wikipedia.org/wiki/Operating_system%EF%BC%89" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Operating_system）</a></li><li>《现代操作系统》《操作系统概念》（书籍，只做推荐）</li></ul>`,39)])])}const E=t(l,[["render",h]]);export{c as __pageData,E as default};
